import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create the plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load the orb-decor texture
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : Promise.resolve(null);

  // Create material with TSL nodes
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create the mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position and rotation
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition[0],
      config.scenePosition[1],
      config.scenePosition[2]
    );
  }

  if (config.sceneRotation) {
    mesh.rotation.set(
      config.sceneRotation[0],
      config.sceneRotation[1],
      config.sceneRotation[2]
    );
  }

  if (config.sceneScale) {
    mesh.scale.set(
      config.sceneScale[0],
      config.sceneScale[1],
      config.sceneScale[2]
    );
  }

  // Load and apply texture
  texturePromise.then((tex) => {
    if (tex) {
      material.colorNode = texture(tex);
      material.needsUpdate = true;
    }
  });

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
